#!/bin/bash
sed -i 's/import { auth, signInWithGoogle, logout } from ".\/lib\/firebase";/import { auth, signInWithGoogle, logout } from ".\/lib\/firebase";\nimport { syncDataToDrive, syncDataFromDrive, getDriveToken } from ".\/lib\/driveSync";\nimport { Cloud, Download, Upload } from "lucide-react";/g' src/App.tsx

sed -i 's/const \[authLoading, setAuthLoading\] = useState(true);/const \[authLoading, setAuthLoading\] = useState(true);\n  const \[syncing, setSyncing\] = useState(false);\n  const \[hasDriveToken, setHasDriveToken\] = useState(false);/g' src/App.tsx

sed -i 's/setUser(currentUser);/setUser(currentUser);\n      if (currentUser \&\& getDriveToken()) setHasDriveToken(true);/g' src/App.tsx

sed -i 's/        <div className="flex flex-wrap justify-center gap-4">/        <div className="flex flex-wrap justify-center items-center gap-4">\n          {hasDriveToken && (\n            <div className="flex gap-2 mr-4">\n              <button disabled={syncing} onClick={async () => { setSyncing(true); try { await syncDataFromDrive(); alert("Dados carregados com sucesso do Drive!"); window.location.reload(); } catch(e) { alert("Erro ao carregar do drive"); } setSyncing(false); }} className="px-3 py-2 rounded-full text-sm font-bold bg-green-50 text-green-600 hover:bg-green-100 flex items-center gap-1" title="Carregar do Drive">\n                <Download className="w-4 h-4" /> <span className="hidden sm:inline">Carregar</span>\n              <\/button>\n              <button disabled={syncing} onClick={async () => { setSyncing(true); try { await syncDataToDrive(); alert("Dados salvos no Drive com sucesso!"); } catch(e) { alert("Erro ao salvar no drive"); } setSyncing(false); }} className="px-3 py-2 rounded-full text-sm font-bold bg-blue-50 text-blue-600 hover:bg-blue-100 flex items-center gap-1" title="Salvar no Drive">\n                <Upload className="w-4 h-4" /> <span className="hidden sm:inline">Salvar</span>\n              <\/button>\n            <\/div>\n          )}/g' src/App.tsx
